SetKCol-1	$0f	DC.L VDKeyGetKRCol-1 $10	DC.L VDKeyGetKGCol-1 $11	DC.L VDKeyGetKBCol-1 $12	DC.L VDKeySetKDiss-1 $13	DC.L VDKeyGetKDiss-1 $14	DC.L VDKeySetNKDiss-1 $15	DC.L VDKeyGetNKDiss-1 $16	DC.L VDOutSetStd-1	$17	DC.L VDOutGetStd-1	$18	DC.L VDOutControl-1	$19	DC.L VDOutStatus-1	$1a	DC.L VDGetFeatures-1 $1b	DC.L VDInControl-1	$1c	DC.L VDGGControl-1	$1d	DC.L VDGGStatus-1	$1eENDFPT		; 	ENDP;;           copy  VDInit.asm	 ;Housekeeping routines	TITLE 'Video I/O Overlay Manager Init. Routines';______________________________________________________________________________;;        VDBootInit;;       input: none;;      output: none;______________________________________________________________________________	EXPORT VDBootInitVDBootInit	PROC	lda #0	;system	pha	lda #TheTool	;tool 33	pha	PushLong #0	_SetWAP	;set WAP to zero	lda #0	clc	rtl	ENDP;______________________________________________________________________________;;        VDStartup;;       input: ProgramID:WORD - ID to use with the Memory Manager;;      output: none;______________________________________________________________________________	EXPORT VDStartupVDStartup	PROC		;using data;Save processor status	jsl IncBusyFlg	;inc. busy flag	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank	ldx #ActvMask	;get active bit to be ored in	stx ActDeact	;set for activate	tax	;save info in x	and #SlotMask	;only want slot value	sta slot	beq error	;branch if no device found	ldy #AlreadyStarted	;assume error	txa	;get info back	bmi errorAS	;branch if already started	jmp oksofarErrorY	tay	;put error in yErrorAS		; 	jsl $e10068	;dec. busy flag	jmp Rid0	;return with errorerror		; ;;We arrive here if the WAP hasnt already been set, so look for message;;First get a new handle for message to go into	PushLong #0	;space for result	PushLong #20	;size of message in	bytes	PushWord #$4021	;User ID for memory	manager	PushWord #$c018	;attributes, locked	PushLong #0	;address (not used)	_NewHandle	;get a new handle	sta ERRORX	PullLong MyMessHdl	;save message handle	ldy ERRORX	bne ErrorAS;Now get the message from the message center	PushWord #2	;get message	PushWord #MessNo	PushLong MyMessHdl	;My Message Handle (data area)	_MessageCenter	bcs NoMessage	;branch if no message or error;Clear out message signature so we wont	think we got one	lda #0	sta MyMessSig	sta MyMessSig;We arrive here when the message has been found, so lets see if it's really;mine	PushLong MyMessHdl	;handle to the message	PushLong #MyMessData ;Pointer to My message data area	PushLong #20	;No. of bytes	_HandToPtr	;copy message into my data area	bcs NoMessage	;branch if error;Now check the signature for $21211212	lda MyMessSig	cmp #$2121	bne MessError	;branch if not mine	lda MyMessSig+2	cmp #$1212	bne MessError	;branch if not mine;Now see if the slot is not zero (zero if video overlay card not found)	ldy #Novideodevice	;error, no device found	sty ErrorX	lda MessSlot	and #SlotMask	;look at slot	beq NoCdMesg	;branch if bad slot;Now take out the slot no. and status from message	lda MessSlot	;good slot	jmp oksofar;;We arrive here if there was no message	or incorrect message or errorNoMessage		; MessError		; ;;Now see if card is	there (takes lots of time);;Now get zero page for finding the card	PushLong #0	;space for result	PushLong #10	;size of direct page needed	PushWord #$4021	;User ID for memory	manager	PushWord #$c005	;attributes, locked	PushLong #0	;address	_NewHandle	;get a new handle	sta ERRORX	;save error	PullLong ZPHandle	;save zero page handle	lda ErrorX	;get error	bne NoCdFound	;branch if error occured	phd	;save current D	PushLong ZPHandle	;put handle back onto stack	tsc	;turn stack into direct page	tcd	lda [1]	;deref the pointer	sta ErrorX	tcd	;set to new direct page	pla	;get long off stack	pla	;get long off stack	jsr FindCard	pld	;restore direct page	lda slot	;get slot (not zero	if found)	bne NowAddMess	;branch if found card	ldy #Novideodevice	;error, no device found	sty ErrorX;We arrive here when there was no message and was unable to	find the cardNoCdFound		; 	PushLong ZPHandle	_DisposeHandleNoCdMesg		; 	PushLong MyMessHdl	_DisposeHandle	jsl $e10068	;dec. busy flag	ldy ErrorX	jmp Rid0NowAddMess		; ;OK, we found the card, now add the message	ora ActDeact	;or on active bit	sta MessSlot	;set slot fields of	message	EXPORT ChgMessChgMess		;       	lda #$2121	sta MyMessSig	;setup signature	lda #$1212	sta MyMessSig+2;Now move the data to the handle	PushLong #MyMessData ;Pointer to My message data area	PushLong MyMessHdl	;handle to the message	PushLong #20	;No. of bytes	_PtrToHand	;copy message into my data area;Now send the message to the message center	PushWord #1	;add message	PushWord #MessNo	PushLong MyMessHdl	;My Message Handle (data area)	_MessageCenter	lda slot	;get slot no.oksofar		; 	ora ActDeact	;or on active bit if activate	tax	;save for now;**************************	lda #0	;system	pha	lda #TheTool	;tool 33	pha	lda #0	;high word	pha	txa	;get active and TMO	flag and slot	pha	_SetWAP;**************************	PushLong MyMessHdl	_DisposeHandle	;**This determines the video mode NTSC/PAL	ldx #NTSC	;assume its NTSC	lda >LANGSEL	;get softswitch (language select)	and #$0010	;and out all but NTSC/PAL bit	beq wasNTSC	;branch if was NTSC	ldx #PALwasNTSC	stx VideoStd	;save at video standard		jsl $e10068	;dec. busy flag	ldy #0	jmp Rid0	EXPORT ERRORXERRORX		;       	DS.B 2	EXPORT ActDeactActDeact		;       	DS.B 2	;space to store if active or deactive	EXPORT MyMessHdlMyMessHdl		;       	DS.B 4	;My message handle save areaZPHandle	DS.B 4	;My zero page handle save area	EXPORT MyMessDataMyMessData		;       	DS.B 4	;Reserved Space LONG	DS.B 2	;Reserved Space WORD	EXPORT MyMessSigMyMessSig		;       	DS.B 4	;My signature $21211212	EXPORT MessSlotMessSlot		;       	DS.B 2	;15-active,8-flag, 0-7 slot	DS.B 10	;Extra Space for now		EXPORT VideoStdVideoStd	DS.B 2	;saved video standard area (NTSC or PAL)	ENDP;______________________________________________________________________________;;        VDVersion;;       input: none;;      output: Version:WORD - This tools version number;______________________________________________________________________________	EXPORT VDVersionVDVersion	PROCVersion	equ 7	; stack relative	lda #TheVDVersionNum	sta Version,s	lda #0	clc	rtl	ENDP;______________________________________________________________________________;;        VDShutDown;;       input: none;;      output: none;______________________________________________________________________________	EXPORT VDShutDownVDShutDown	PROC	jsl IncBusyFlg	;inc. busy flag;Save processor status, turn off interrupts	php	phb	phk	plb	cmp #0	;get status	bpl ErrorOut	;do nothing if not active	and #$7fff	;and off active bit	(bit-15)	sta slot	sta MessSlot;First get a new handle for message to go into	PushLong #0	;space for result	PushLong #20	;size of message in	bytes	PushWord #$4021	;User ID for memory	manager	PushWord #$c018	;attributes, locked	PushLong #0	;address (not used)	_NewHandle	;get a new handle	sta ErrorX	;save error	PullLong MyMessHdl	;save message handle	ldy ErrorX	beq oktogoErrorOut		; 	jsl $e10068	;dec. busy flag	ldy #0	jmp Rid0	;return without updating messageoktogo		; 	ldx #0	stx ActDeact	;set for deactive	jmp ChgMess	;go update message	ENDP;______________________________________________________________________________;;        VDReset;;       input: none;;      output: none;______________________________________________________________________________	EXPORT VDResetVDReset	PROC	lda #0	clc	rtl	ENDP;_____________________________________________________________________________;;        VDStatus;;       input: none;;      output: status:WORD - TRUE if the tool set is initialized;______________________________________________________________________________	EXPORT VDStatusVDStatus	PROCSigRtn	equ 7	rol a	;active bit into carry	rol a	;active bit into bit-0	and #$0001	;and out all but bit-0 (active bit)	sta SigRtn,s	;put on stack	lda #0	clc	rtl	ENDP;_____________________________________________________________________________;;        NotImp;;       input: none;;      output: none;______________________________________________________________________________	EXPORT NotImpNotImp	PROC	txa	; tool set number and function were;		; in X on entry	xba	; Tool set number in LSB, move to MSB	ora #$00FF	; FF for error code	sec	; indicate error on	return	rtl	ENDP;_____________________________________________________________________________;;        FindCard;;     purpose: To determine the presence of the Apple II Video Overlay Card;;       input: none;;      output: none;        NOTE: This	routine requires a direct page;        NOTE: Upon	return slot will contain the slot number (zero if not found);        NOTE: This	routine turns off interrupts for around	1/6 of a second.;______________________________________________________________________________	EXPORT FindCardFindCard	PROC	php	;save status	sei	;turn off interrupts	lda Reg_ptr_lo	;save direct page values	sta Saved_ZP	lda Reg_ptr_lo+2	sta Saved_ZP+2	lda Reg_ptr_lo+4	sta Saved_ZP+4;Now see if card is	there	longa off	longi off	sep #$30	;8-bit mode	jsr Get_Mach_Info	;go get machine info (TRON out there?)	rep #$30	;16-bit mode	longi on	longa on	lda Saved_ZP	;restore zero page stuff	sta Reg_ptr_lo	lda Saved_ZP+2	sta Reg_ptr_lo+2	lda Saved_ZP+4	sta Reg_ptr_lo+4	plp	;restore status	rtsSaved_ZP	DS.B 6	;zero page saved area	EXPORT SLOTSLOT		;       	DC.B $00	DC.B $00	;high byte (for 16-bit loads)	ENDP;           COPY  PRESENCE.ASM	 ;TRON PRESENCE TEST ROUTINES	EXPORT DataData	PROC	EXPORT proc_typeproc_type	DS.B 1	EXPORT stat_addr_histat_addr_hi	DC.B $C0	EXPORT stat_addr_lostat_addr_lo	DC.B $00	DC.B $90	DC.B $A0	DC.B $B0	DC.B $C0	DC.B $D0	DC.B $E0	DC.B $F0	EXPORT rom_addr_hirom_addr_hi	DC.B $C1	EXPORT rom_addr_lorom_addr_lo	DC.B $00	EXPORT min_acceptmin_accept	DS.B 1	EXPORT max_acceptmax_accept	DS.B 1	EXPORT range_resultrange_result	DS.B 1	EXPORT success_countsuccess_count	DS.B 1	EXPORT temptemp	DS.B 1	EXPORT is_resultis_result	DS.B 1	EXPORT delay_tempdelay_temp	DS.B 1	ENDP******************************************************************************************; determine machine	type (code passed in X by MACH_TEST); store result in global proc_type******************************************************************************************	EXPORT MACHINE_TYPEMACHINE_TYPE	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	JSR MACH_TEST	STX proc_type	RTS	ENDP***********************************************************************************;CODE TO FIND SLOT TRON CARD IS IN**********************************************************************************************************************************************************************************;Monitor status bit	until it shows a 1.	 If no 1 after 255 passes of;WAIT_FOR_ONE, fail	(0 is returned in A).  If 1 shows within time range, call;TIME_0_TO_1 to monitor time it takes to go high again.  This time (0->1) will;determine if this is the TRON status register or not.********************************************************************************	EXPORT Wait_for_1Wait_for_1	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	LDY #$00	LDX #$00WAIT_FOR_ONE	INX	BEQ NO_CHANGE1	lda #$05	jsr Wait	;about 140us delay	LDA [reg_ptr_lo],Y	AND #stat_mask	CMP #stat_mask	BNE WAIT_FOR_ONE	jsr Time_0_to_1NO_CHANGE1	TXA	RTS	ENDP***********************************************************************************************;Wait for a 0 (if not already 0) and find number of loops it takes to get 1;If no 0 within 255	passes of WAIT_FOR_0, fail (0 is returned in A);Otherwise count # of passes of HAVE_A_O it takes to get a 0.  Return number in	A.;If no 1 within 255	passes of HAVE_A_0,	fail (0 is returned	in A)***********************************************************************************************	EXPORT TIME_0_TO_1TIME_0_TO_1	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	LDY #$00	LDX #$00WAIT_FOR_0	INX	BEQ NO_CHANGE2	lda #$02	jsr WAIT	;about a 49us delay	LDA [reg_ptr_lo],Y	AND #stat_mask	CMP #$00	BNE WAIT_FOR_0	LDX #$00HAVE_A_0	INX	;2	BEQ NO_CHANGE2	lda #$05	jsr wait	;about a 140us delay	LDA [reg_ptr_lo],Y	;4	AND #stat_mask	;2	CMP #stat_mask	;2	BNE HAVE_A_0	;3NO_CHANGE2	TXA	RTS	ENDP***********************************************************************************************;Looks at bit 2 of status.  If it's zero, wait for a one and then, when a 0;shows again, time 0-->1.  If its's one, wait for a zero and then find time it;takes to change to	1.  Then number of loops required for 0-->1 will be;returned in A.  If	a time-out is discovered, a 0 is returned.********************************************************************************	EXPORT Time_VBLTime_VBL	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	TYA	;save Y on stack	PHA	LDY #$00	LDA [reg_ptr_lo],Y	AND #stat_mask	CMP #$00	BEQ IS_ZERO	;if it's zero, wait for a one and find the time it takes;		        ;to change to a 0	JSR TIME_0_TO_1	JMP DONE1IS_ZERO	JSR Wait_for_1DONE1	STA temp	;save A since we need A to pull from stack	PLA	TAY	;restore Y	LDA temp	RTS	ENDP***********************************************************************************************;routine to check if value in A is < max_accept and > min_accept;input ---  A (value to check);      ---  min_accept, max_accept (min	and max values);output --  range_result (#$00 if fail,	#$01 if pass)***********************************************************************************************	EXPORT WITHIN_RANGEWITHIN_RANGE	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	CMP min_accept	BMI FAIL1	CMP max_accept	BPL FAIL1	LDA #$01	STA range_result	JMP DONE2FAIL1	LDA #$00	STA range_resultDONE2	RTS	ENDP;*****************************************************************************;;;*****************************************************************************	EXPORT TESTTEST	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	lda #$00	sta reg_ptr_hi+1	LDA #$C0	STA reg_ptr_hi	LDA #$B0	STA reg_ptr_lo	LDY #$00test_again	JSR TIME_VBL	CLC	ADC #$B0;               JSR	    cout	INY	CPY #$05	BNE test_again	RTS	ENDP***********************************************************************************************;RUN_10 runs TIME_SCAN_INT 10 times. If	card passes 10 times in a row, it's a TRON***********************************************************************************************	EXPORT RUN_10RUN_10	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	LDA #$00	STA success_countREPEAT	JSR Time_VBL	JSR WITHIN_RANGE	LDA range_result	BEQ FAIL3	INC success_count	LDA success_count	CMP #test_count	BNE REPEATFAIL3	RTS	ENDP***********************************************************************************************;Determines if slot	indicated by rom_ptr has non-disk ROM ID;input -- ROM address in rom_ptr_lo and	rom_ptr_hi;output -- A is 0 if not non-disk ROM, 1 if it is***********************************************************************************************	EXPORT IS_NON_DISKIS_NON_DISK	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	TYA	;save Y on stack	PHA	LDY #$05	LDA [rom_ptr_lo],Y	CMP #$38	BNE FAIL4	LDY #$07	LDA [rom_ptr_lo],Y	CMP #$18	BNE FAIL4	LDY #$0B	LDA [rom_ptr_lo],Y	CMP #$01	BNE FAIL4	LDY #$0C	LDA [rom_ptr_lo],Y	;check for 80 column card.  If it is, fail..	CMP #$88	;this slot needs to	be checked for TRON.. 	BEQ FAIL4	;since TRON could be in slot 3	LDA #$01	STA is_result	JMP DONEFAIL4	LDA #$00	STA is_resultDONE	PLA	;restore Y	TAY	LDA is_result	RTS	ENDP***********************************************************************************************;Determines if slot	indicated by rom_ptr has non-disk ROM ID;input -- ROM address in rom_ptr_lo and	rom_ptr_hi;output -- A is 0 if not disk ROM, 1 if	it is***********************************************************************************************	EXPORT IS_DISKIS_DISK	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	TYA	;save Y on stack	PHA	LDY #$01	LDA [rom_ptr_lo],Y	CMP #$20	BNE FAIL5	LDY #$03	LDA [rom_ptr_lo],Y	CMP #$00	BNE FAIL5	LDY #$05	LDA [rom_ptr_lo],Y	CMP #$03	BNE FAIL5	LDA #$01	STA is_result	JMP DONEFAIL5	LDA #$00	STA is_resultDONE	PLA	;restore Y	TAY	LDA is_result	RTS	ENDP***********************************************************************************************    ;Test C(8+s)00 bit 2 to see if it is toggling at a rate between lower and upper	bound.  Output ;number of any slots that pass test.  Bit 2 is the VBL status in TRON status;register.***********************************************************************************************	EXPORT FIND_TRONFIND_TRON	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	lda #0	sta slot	;init. slot not found	sta rom_ptr_hi+1	sta reg_ptr_hi+1	;set banks to zero	LDA rom_addr_hi	STA rom_ptr_hi	LDA rom_addr_lo	STA rom_ptr_lo	LDA stat_addr_hi	STA reg_ptr_hi	LDY #$01	;init. slot to tryNEXT_SLOT	JSR IS_NON_DISK	;see if slot contains non-disk device ROM ID	BNE FAIL6	JSR IS_DISK	;see if slot contains disk device ROM ID	BNE FAIL6	LDA stat_addr_lo,Y	STA reg_ptr_lo	JSR RUN_10	LDA success_count	CMP #test_count	BNE FAIL6	TYA	STA slot	rtsFAIL6	INY	INC rom_ptr_hi	;point to next card's rom	CPY #not_a_slot	BNE NEXT_SLOT	RTS	ENDP*********************************************************************************** ;****************************************************************************; This performs the	same as a firmware WAIT routine;****************************************************************************	EXPORT WAITWAIT	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	sec	;enter with count in A-reg.Wait2	pha	;delay is:Wait3	sbc #$01	bne Wait3	;13+11*A+5*A*A cycles	pla	;at 1.023 usec per cycle	sbc #$01	bne Wait2	rts	ENDP***********************************************************************************************; get machine-dependent info (processor	type and TRON card slot #); MACHINE_TYPE gets	processor type, FIND_SLOT gets TRON slot #***********************************************************************************************	EXPORT GET_MACH_INFOGET_MACH_INFO	PROC		;using   equates		;using   data	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.	lda >$00C036	;get soft switch speed ctrl	sta save_speed	;save it for latter	and #$7f	;force to slow speed	sta >$00c036	;now we are running	slow	JSR MACH_TEST	;find processor type	STX proc_type	TXA	BNE NOT_IIGS	;if MACH_TEST returns 0, it's a IIGS (65186) machine	LDA #min_IIGS	STA min_accept	LDA #max_IIGS	STA max_accept	JMP RUN_FIND_TRONNOT_IIGS	LDA #min_IIe	STA min_accept	LDA #max_IIe	STA max_acceptRUN_FIND_TRON		; 	JSR FIND_TRON	;find slot TRON is in	lda save_speed	;get saved speed value	and #$80	;only look at speed	bit	beq was_slow	;branch if was already slow speed	lda >$00C036	;get soft switch speed ctrl	ora #$80	;force back to fast	speed	sta >$00c036	;now we are running	fast againwas_slow		; 	LDA slot	BNE FOUND_TRON	JMP DONEFOUND_TRON		; 	tay	lda Stat_addr_lo,y	;get low byte of slots address	sta slotDONE	RTSSave_Speed	DS.B 1	;saved system speed	value	ENDP;****************************************************************************************;determine machine (processor) type of the machine that is running this program		    ;input --- none;output -- machine type code in X register.  0=II_GS, 1=65C02 machine, 2=6502 machine.	EXPORT MACH_TESTMACH_TEST	PROC	longa off	;use 8-bit Acc	longi off	;use 8-bit index reg.II_GS	EQU $00SIXTY_5C02	EQU $01SIXTY_502	EQU $02	SED	LDA #$99	CLC	ADC #$01	BMI ITS_A_6502	CLC	XCE	BCC ITS_A_65C02ITS_A_GS	SEC	;set emul mode...	XCE	;	SEP #$30	;8 bit accum, index	LDX #II_GS	;load ii_gs id number	JMP DONEITS_A_65C02	LDX #SIXTY_5C02	JMP DONEITS_A_6502	LDX #SIXTY_502DONE	CLD	RTS	longa on	;use 16-bit Acc	longi on	;use 16-bit index reg.	ENDP;           copy  Features.asm	 ;Features routine;______________________________________________________________________________;;        MDGetFeatures;;       input: wordspace:WORD - Space for result;              Selector:WORD - Selects which feature info. to return;;      output: VDFeature:WORD - Feature	information;______________________________________________________________________________	EXPORT VDGetFeaturesVDGetFeatures	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3Selector	equ RTL2+3VDFeature	equ Selector+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank	ldy #InvalidSelect	;assume invalid selector error	lda Selector,s	;get selector value	beq Ridjump	;branch if invalid ($0000 passed)	cmp #LastFeature	;see if selector is	valid	bcc goodselect	;branch if selector	fine	lda #NotAvail	;if beyond list, force not available	bra Force_NotAGoodSelect		asl A	;multiply by two	tax	;use as index into table;**For NTSC/PAL	lda VideoStd	;get video standard	cpx #6	;is it InVStandards?	beq @1	;branch if it was (returns determined video standard)	cpx #8	;is it OutVStandards?	beq @1	;branch if it was (returns determined video standard)	lda FeatureTbl-2,x	;get feature from table@1	ldy #0	;indicate no errorsForce_NotA		; 	sta VDFeature,s	;store as returned valueRidJump	jmp Rid2;---------------------;Features table;--------------------FeatureTbl		; 	DC.W Avail	;VideoOverlay	DC.W NotAvail	;FrameGrabber	DC.W NTSC	;InVStandards	DC.W NTSC	;OutVStandards	DC.W 8	;KeyDissLevels	DC.W 8	;NKeyDissLevels	DC.W Yes	;AdjSideEffect	DC.W 4	;KeyColorBits	DC.W Avail	;InHueAdj	DC.W Avail	;InSatAdj	DC.W NotAvail	;InContrastAdj	DC.W NotAvail	;InBrightAdj	DC.W Avail	;OutSetup	DC.W Avail	;OutChromFltr	DC.W Avail	;OutExtBlank	DC.W Avail	;KeyEnhDiss	DC.W Avail	;LineInterrupts	DC.W Avail	;GGBus	DC.W Avail	;DualOut	DC.W Avail	;TextMonoOver	ENDP;------------------------------------------------------------------------------;; Rid code (gets rid of passed parameters off the stack);;-----------------------------------------------------------------------------	EXPORT RidRid	PROC;------------------------------------------------------------------------------;Gets rid of no paramters;------------------------------------------------------------------------------	EXPORT Rid0Rid0		;       	plb	;restore users data	bank	plp	;restore processor status (interrupts)Rid0X		; 	tya	;get error (if any)	sec	;assume error	beq noerror	;branch if no error	rtl	;return with errornoerror		; 	clc	;indicate no errors	rtl;------------------------------------------------------------------------------;Gets rid of 2-bytes worth of paramters;------------------------------------------------------------------------------	EXPORT Rid2Rid2		;       	plb	;restore users data	bank	plp	lda 5,s	sta 5+2,s	lda 3,s	sta 3+2,s	lda 1,s	sta 1+2,s	pla	bra Rid0X;------------------------------------------------------------------------------;Gets rid of 4-bytes worth of paramters;------------------------------------------------------------------------------	EXPORT Rid4Rid4		;       	plb	;restore users data	bank	plp	lda 5,s	sta 5+4,s	lda 3,s	sta 3+4,s	lda 1,s	sta 1+4,s	pla	pla	bra Rid0X;------------------------------------------------------------------------------;Gets rid of 6-bytes worth of paramters;------------------------------------------------------------------------------	EXPORT Rid6Rid6		;       	plb	;restore users data	bank	plp	lda 5,s	sta 5+6,s	lda 3,s	sta 3+6,s	lda 1,s	sta 1+6,s	pla	pla	pla	bra Rid0X	ENDP;           copy  Input.asm	 ;Input routines;______________________________________________________________________________;;        VDInControl;              (Sets the video input control values);;      input:  Selector:WORD - Selects which input control value to set;              InCtrlValue:WORD - The input control value;;      output: None;______________________________________________________________________________	EXPORT VDInControlVDInControl	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3InCtrlValue	equ RTL2+3Selector	equ InCtrlValue+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldy #InvalidParam	;assume invalid 'InCtrlvalue'	lda InCtrlValue,s	;get control value	tax	;save in x for now	beq OkValue	;branch if ok	cpx #1	beq OkValue	jmp not4	;not a vailid parameterOkValue		; 	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #Genlock	bne not4	;branch if not Genlock select;----------------------; GenLock selected;----------------------	longa off	longi off	sep #$30	phx	;save x	ldx slot	;get slot card is in	lda >$00c005,x	plx	;restore x	and #$df	;and it out (assume	its enabled)	cpx #1	;see if enabled	beq GLjmp	;branch if enabled	ora #$20	;or it disabledGLjmp		; 	ldx slot	sta >$00c005,x	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errorsnot4		; 	jmp Rid4	ENDP;______________________________________________________________________________;;        VDInStatus;              (Gets the current input status information);;      Input:  WordSpace: WORD, Space for result;              Selector: WORD, Selects what to status;;      output: InStatus: Word, Current Status Value;______________________________________________________________________________	EXPORT VDInStatusVDInStatus	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3Selector	equ RTL2+3InStatus	equ Selector+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldx #0	;assume disabled	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #GenLock	bne not2	;branch if not Genlock;----------------------; Genlock selected;----------------------	longa off	longi off	sep #$30	ldx slot	;get slot no.	lda >$00c005,x	ldx #0	and #$20	;and it out (assume	its enabled)	bne GLjmp	;branch if enabled	ldx #1GLjmp		; 	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot2	cmp #VideoDetect	bne not3	;branch if not videodetect;----------------------; Video Detect selected;----------------------	longa off	longi off	sep #$30	ldx slot	lda >$00c000,x	ldx #0	and #$08	;and it out (assume	its disabled)	beq VDjmp	;branch if disabled	ldx #1	;it was enabledVDJmp		; 	rep #$30	longi on	longa on	bra OutOK	;return without errorsnot3	cmp #GenLocked	bne not4	;branch if invalid selector;----------------------; GenLocked Selected;----------------------	longa off	longi off	sep #$30	ldx slot	lda >$00c000,x	ldx #0	and #$10	;and it out (assume	its external)	beq JLkjmp	;branch if genlocked	ldx #1	;it wasn'tJLkJmp		; 	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errors	txa	sta InStatus,s	;set returned valuenot4		; 	jmp Rid2	ENDP;______________________________________________________________________________;;        VDInSetStd;              (Sets the video composite input standard.);;      Input:  VDInSetStd:WORD, Video input standard;;      output: None;______________________________________________________________________________	EXPORT VDInSetStdVDInSetStd	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3InSetStd	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank	ldy #InvalidParam	;assume invalid for	now	lda InSetStd,s	;get input standard;**For PAL/NTSC	cmp VideoStd	;is it the determined video standard	bne notgood	ldy #0	;was goodnotgood		; 	jmp Rid2	ENDP;______________________________________________________________________________;;        VDInGetStd;              (Gets the currently selected video composite	input standard.);;      Input:  WordSpace: WORD, Space for result;;      output: InStandard: WORD, current video output standard;______________________________________________________________________________	EXPORT VDInGetStdVDInGetStd	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3InStandard	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;**For PAL/NTSC	lda VideoStd	;get determined video standard	sta InStandard,s	ldy #0	jmp Rid0	ENDP;______________________________________________________________________________;;        VDInConvAdj;              (Performs video input adjustment);;      input:  Selector:WORD - Selects which input control value to set;              AdjFunction:WORD - The function to perform;;      output: None;______________________________________________________________________________	EXPORT VDInConvAdjVDInConvAdj	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3AdjFunction	equ RTL2+3Selector	equ AdjFunction+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	lda Selector,s	;get selector value	ldx #8	;get XICOR select bit	cmp #InHueAdj	beq OkValue	;branch if ok	ldx #4	;get XICOR Sat. bit	cmp #InSatAdj	beq OkValue	;branch if ok	ldy #InvalidSelect	;assume invalid selector	jmp not4	;not a vailid selectorOkValue		; 	ldy #InvalidParam	;assume bad parameter error	lda AdjFunction,s	;get selector value	cmp #AdjSave	bne not1	;branch if not a save function;----------------------; AdjSave selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda #0	sta >$00c006,x	;force a save to occur	plx	rep #$30	longa on	longi on	bra OutOKnot1	cmp #AdjInc	bne not2	;branch if not an AdjInc;----------------------; AdjInc selected;----------------------	txa	longa off	longi off	sep #$30	phx	ldx slot	sta >$00c006,x	;set the initial bits	nop	nop	nop	nop	nop	ora #$01	;turn on step bit	sta >$00c006,x	nop	nop	nop	nop	nop	and #$fe	sta >$00c006,x	plx	rep #$30	longa on	longi on	bra OutOKnot2	cmp #AdjDec	bne not4	;branch if not an AdjDec;----------------------; AdjDec Selected;----------------------	txa	longa off	longi off	sep #$30	ora #02	;or in dec.	phx	ldx slot	sta >$00c006,x	;set the initial bits	nop	nop	nop	nop	nop	ora #$01	;turn on step bit	sta >$00c006,x	nop	nop	nop	nop	nop	and #$fe	;turn off step bit	sta >$00c006,x	plx	rep #$30	longa on	longi onOutOK	ldy #0	;indicate no errorsnot4		; 	jmp Rid4	ENDP;           copy  Keyer.asm	 ;Keyer routines;______________________________________________________________________________;;        VDKeyControl;              (Sets the keyer control values);;      input:  Selector:WORD - Selects which keyer control value to set;              KeyerCtrlVal:WORD - The keyer control value;;      output: None;______________________________________________________________________________	EXPORT VDKeyControlVDKeyControl	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3KeyerCtrlVal	equ RTL2+3Selector	equ KeyerCtrlVal+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldy #InvalidParam	;assume invalid 'InCtrlvalue'	lda KeyerCtrlVal,s	;get control value	tax	;save in x for now	beq OkValue	;branch if ok	cpx #1	beq OkValue	jmp not4	;not a vailid parameterOkValue		; 	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #KColorEnable	bne not1	;branch if not Key color enable;----------------------; Key color enable selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c005,x	plx	and #$bf	;and it out (assume	its enabled)	cpx #1	;is it enabled?	beq KCjmp	;branch if enabled	ora #$40	;or it disabledKCjmp		; 	ldx slot	sta >$00c005,x	rep #$30	longi on	longa on	bra OutOknot1	cmp #KeyEnhDiss	bne not4	;branch if not Key color enable;----------------------; Enhanced Dissolve	was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c003,x	plx	and #$f7	;and it out (assume	its disabled)	cpx #1	bne EDjmp	;branch if want disabled	ora #$08	;or it enableEDjmp		; 	ldx slot	sta >$00c003,x	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errorsnot4		; 	jmp Rid4	ENDP;______________________________________________________________________________;;        VDKeyStatus;              (Gets the current Keyer control status information);;      Input:  WordSpace: WORD, Space for result;              Selector: WORD, Selects what to status;;      output: KeyerStatus: Word, Current Status Value;______________________________________________________________________________	EXPORT VDKeyStatusVDKeyStatus	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3Selector	equ RTL2+3KeyerStatus	equ Selector+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldx #0	;assume disabled	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #KColorEnable	bne not2	;branch if not key color enable;----------------------; Key color enable selected;----------------------	longa off	longi off	sep #$30	ldx slot	lda >$00c005,x	ldx #0	and #$40	;and it out (assume	its enabled)	bne GLjmp	;branch if enabled	ldx #1	;show disabledGLjmp		; 	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot2	cmp #KeyEnhDiss	bne not4	;branch if not enhanced dissolve;----------------------; Enhanced dissolve	selected;----------------------	longa off	longi off	sep #$30	ldx slot	lda >$00c003,x	ldx #0	and #$08	;and it out (assume	its disabled)	beq VDjmp	;branch if disabled	ldx #1	;it was enabledVDJmp		; 	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errors	txa	sta KeyerStatus,s	;set returned valuenot4		; 	jmp Rid2	ENDP;______________________________________________________________________________;;        VDKeySetKCol;              (Sets the key color value);;      Input:  RedValue:Word, Red component of control color;              GreenValue:Word, Green component of control color;              BlueValue:Word, Blue component of control color;;      output: None;______________________________________________________________________________	EXPORT VDKeySetKColVDKeySetKCol	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3BlueValue	equ RTL2+3GreenValue	equ BlueValue+2RedValue	equ GreenValue+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	lda RedValue,s	;get red value	lsr a	lsr a	lsr a	lsr a	sei	;turn off interrupts	sta SaveitR	lda BlueValue,s	;get blue part	xba	lsr a	lsr a	lsr a	lsr a	and #$000f	sta saveit	;save it for now	lda GreenValue,s	;get green part	xba	and #$00f0	;and out unwanted bits	ora saveit	;or in blue bits	longa off	longi off	sep #$30	ldx slot	sta >$00c004,x	;set blue and green	lda >$00c005,x	and #$f0	ora saveitR+1	;or in red part	sta >$00c005,x	rep #$30	longi on	longa on	ldy #0	jmp Rid6Saveit	DS.B 2SaveitR	DS.B 2	ENDP;______________________________________________________________________________;;        VDKeyGetKRCol;              (Gets the Red component of the key color);;      Input:  WordSpace: WORD;;      output: RedValue: WORD;______________________________________________________________________________	EXPORT VDKeyGetKRColVDKeyGetKRCol	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3RedValue	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	longa off	longi off	sep #$30	ldx slot	lda >$00c005,x	;get red part of key color	rep #$30	longi on	longa on	xba	;put into high byte	asl a	asl a	asl a	asl a	and #$f000	;mask out unwanted bits	sta RedValue,s	;put onto stack to return	ldy #0	jmp Rid0	ENDP;______________________________________________________________________________;;        VDKeyGetKGCol;              (Gets the Green component of the key color);;      Input:  WordSpace: WORD;;      output: GreenValue: WORD;______________________________________________________________________________	EXPORT VDKeyGetKGColVDKeyGetKGCol	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3GreenValue	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	longa off	longi off	sep #$30	ldx slot	lda >$00c004,x	;get green part of key color	rep #$30	longi on	longa on	xba	;put into high byte	and #$f000	;mask out unwanted bits	sta GreenValue,s	;put onto stack to return	ldy #0	jmp Rid0	ENDP;______________________________________________________________________________;;        VDKeyGetKBCol;              (Gets the Blue component	of the key color);;      Input:  WordSpace: WORD;;      output: BlueValue: WORD;______________________________________________________________________________	EXPORT VDKeyGetKBColVDKeyGetKBCol	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3BlueValue	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	longa off	longi off	sep #$30	ldx slot	lda >$00c004,x	;get blue part of key color	rep #$30	longi on	longa on	xba	;put into high byte	asl a	asl a	asl a	asl a	and #$f000	;mask out unwanted bits	sta BlueValue,s	;put onto stack to return	ldy #0	jmp Rid0	ENDP;______________________________________________________________________________;;        VDKeySetKDiss;              (Sets the key colors dissolve value);;      Input:  KDissolve:Word, Key colors dissolve value (15-0);;      output: None;______________________________________________________________________________	EXPORT VDKeySetKDissVDKeySetKDiss	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3KDissolve	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldx #0	lda KDissolve,s	cmp #5462	bcc got_it	inx	cmp #16384	bcc got_it	inx	cmp #27308	bcc got_it	inx	inx	cmp #38230	bcc got_it	inx	cmp #49152	bcc got_it	inx	cmp #60075	bcc got_it	inxGot_it		; 	sei	;turn off interrupts	stx saveit	longa off	longi off	sep #$30	ldx slot	lda >$00c003,x	;get dissolve value	and #$f8	;and out old dissolve value	ora saveit	;or in new bits	sta >$00c003,x	;save new key colors dissolve	rep #$30	longi on	longa on	ldy #0	jmp Rid2Saveit	DS.B 2	ENDP;______________________________________________________________________________;;        VDKeyGetKDiss;              (Gets the key colors dissolve value);;      Input:  WordSpace: WORD, Space for result;;      output: KDissolve: WORD, Current	key colors dissolve	value;______________________________________________________________________________	EXPORT VDKeyGetKDissVDKeyGetKDiss	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3KDissolve	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	tax	lda >$00c003,x	;get dissolve value	from card	and #$0007	;look only at dissolve bits	asl a	;times 2 (16 bit table)	tax	;use as index	lda DissTable,x	;get entry from table	sta KDissolve,s	ldy #0	jmp Rid0	EXPORT DissTableDissTable		;       	DC.W 0	;0	DC.W 5462	DC.W 16384	DC.W 27308	DC.W 27308	DC.W 38230	DC.W 49152	DC.W 65535	ENDP;______________________________________________________________________________;;        VDKeySetNKDiss;              (Sets the nonkey colors dissolve value);;      Input:  NKDissolve:Word, nonKey colors dissolve value (15-0);;      output: None;______________________________________________________________________________	EXPORT VDKeySetNKDissVDKeySetNKDiss	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3NKDissolve	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldx #0	lda NKDissolve,s	cmp #5462	bcc got_it	inx	cmp #16384	bcc got_it	inx	cmp #27308	bcc got_it	inx	inx	cmp #38230	bcc got_it	inx	cmp #49152	bcc got_it	inx	cmp #60075	bcc got_it	inxGot_it		; 	txa	asl a	;put bits 0-3 to 4-6	asl a	asl a	asl a	sei	;turn off interrupts	sta saveit	longa off	longi off	sep #$30	;8-bit mode now	ldx slot	lda >$00c003,x	;get dissolve value	and #$8f	;and out old dissolve value	ora saveit	sta >$00c003,x	;save new nonkey colors dissolve	rep #$30	longi on	longa on	ldy #0	jmp Rid2saveit	DS.B 2	ENDP;______________________________________________________________________________;;        VDKeyGetNKDiss;              (Gets the nonkey colors dissolve value);;      Input:  WordSpace: WORD, Space for result;;      output: NKDissolve: WORD, Current nonkey colors dissolve value;______________________________________________________________________________	EXPORT VDKeyGetNKDissVDKeyGetNKDiss	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3NKDissolve	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	tax	lda >$00c003,x	;get dissolve value	from card	and #$0070	;look only at dissolve bits	lsr a	lsr a	lsr a	tax	;use as index	lda DissTable,x	;get entry from table	sta NKDissolve,s	ldy #0	jmp Rid0	ENDP;           copy  Output.asm	 ;Output routines;______________________________________________________________________________;;        VDOutSetStd;              (Sets the video composite output standard.);;      Input:  OutStandard:WORD, Video output standard;;      output: None;______________________________________________________________________________	EXPORT VDOutSetStdVDOutSetStd	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3OutSetStd	equ RTL2+3;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldy #InvalidParam	;assume invalid for	now	lda OutSetStd,s	;get output standard;**For PAL/NTSC	cmp VideoStd	;is it the determined video standard?	bne notgood	ldy #0	;was goodnotgood		; 	jmp Rid2	ENDP;______________________________________________________________________________;;        VDOutGetStd;              (Gets the currently selected video composite	output standard.);;      Input:  WordSpace: WORD, Space for result;;      output: OutStandard: WORD, current video output standard;______________________________________________________________________________	EXPORT VDOutGetStdVDOutGetStd	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3OutStandard	equ RTL2+3;Save processor status	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;**For PAL/NTSC	lda VideoStd	;get the determined video standard	sta OutStandard,s	ldy #0	jmp Rid0	ENDP;______________________________________________________________________________;;        VDOutControl;              (Sets the video composite output control values);;      Input:  Selector: WORD, Selects which control to set;              OutCtrlValue: WORD, The value to set;;      output: None;______________________________________________________________________________	EXPORT VDOutControlVDOutControl	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3OutCtrlValue	equ RTL2+3Selector	equ OutCtrlValue+2;Save processor status, turn off interrupts	php	sei	;turn off interrupts;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank	sta TMOFlag	;save WAP value;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldy #InvalidParam	;first assume bad parameter	lda OutCtrlValue,s	;get control value;Now check passed value for true or false (and External/Graphics)	beq OK_value	cmp #true	beq OK_value	jmp Rid4	;return with Invalid ParamOK_value	tax	;save in x for now	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #TextMonoOver	bne not1	;branch if not TextMonoOver;----------------------; TextMonoOver selected;----------------------	cpx #0	;see if disabled	bne NotDeTMO	;branch if enable;Disable TextMonoOver	lda TMOFlag	and #NotTMOMask	;and off TMO bit	sta TMOFlag	jsr SetupWAP	;go set the new WAP	longa off	longi off	sep #$30	ldx slot;1. Get and save current page select bits	lda >$00c001,x	;get current value	pha	;save it for now;2. Clear page0 and	set page1	and #$cf	;and out page0 and page1	ora #$24	;or on page1 and luma pre_filter	sta >$00c001,x	nop	nop;3. Turn off page 1	and $cf	sta >$00c001,x	;turn page1 off	nop	nop;4. Restore page select bits	pla	;get old value	sta >$00c001,x	;restore value	rep #$30	longi on	longa on	jmp OutOkNotDeTMO		; ;enable TextMonoOver	lda TMOFlag	ora #TMOMask	;or on TMO bit	sta TMOFlag	jsr SetupWAP	;go set the new WAP	ldx slot;1. Wait for vertical interval	longa off	longi off	sep #$30	cli	;enable interrupts while waitingnotVByet	lda >$00c000,x	and #$04	;and it out other bits	beq notVByet	;wait for vertical blank	sei	;disable interrupts	for now;2. Clear page0 and	set page1	lda >$00c001,x	and #$cf	;and out page0 and page1	ora #$24	;or on page1 and luma pre_filter	sta >$00c001,x	nop	nop;3. Toggle luma prefilter from ON to OFF, then ON again.	nop	;wait alittle	and #$fb	;turn off luma pre_filter	sta >$00c001,x	nop	nop	nop	ora #$24	sta >$00c001,x	;turn on luma pre_filter	nop	nop;4. Turn off page 1	and $cf	sta >$00c001,x	;turn page1 off	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot1	cmp #OutChromaFltr	bne not2	;branch if not OutChromafltr;----------------------; OutChroma Filter selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$fb	;and it out (assume	its disabled)	cpx #0	bne CFjmp	;branch if disabled	ora #$04	;or it enabledCFjmp		; 	ldx slot	sta >$00c001,x	rep #$30	longi on	longa on	bra OutOK	;return without errorsnot2	cmp #OutSetup	bne not3	;branch if not outsetup;----------------------; Output Setup selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c003,x	plx	and #$7f	;and it out (assume	its disabled)	cpx #0	bne Setupjmp	;branch if disabled	ora #$80	;or it enabledSetupJmp		; 	ldx slot	sta >$00c003,x	rep #$30	longi on	longa on	bra OutOK	;return without errorsnot3	cmp #OutExtBlank	bne not4	;branch if invalid selector;----------------------; Blanking source select selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c005,x	plx	and #$ef	;and it out (assume	its disabled)	cpx #0	bne SSjmp	;branch if disabled	ora #$10	;or it enabledSSJmp		; 	ldx slot	sta >$00c005,x	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errorsnot4		; 	jmp Rid4	EXPORT TMOFlagTMOFlag		;       	DC.W 0	;text mono over flag (saved area)	DC.B 0	;needed (dont delete)	EXPORT SetupWAPSetupWAP		;       ;**************************	lda #0	;system	pha	lda #33	;tool 33	pha	lda #0	;high word	pha	lda TMOFlag	;get slot (low word)	pha	_SetWAP;**************************	rts	ENDP;______________________________________________________________________________;;        VDOutStatus;              (Gets the current video composite output control status);;      Input:  WordSpace: WORD, Space for result;              Selector: WORD, Selects which control to set;;      output: OutStatus: Word, Current	Status Value;______________________________________________________________________________	EXPORT VDOutStatusVDOutStatus	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3Selector	equ RTL2+3OutStatus	equ Selector+2;Save processor status, turn off interrupts	php	sei	;turn off interrupts;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank	sta TMOFlag	;save WAP;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldx #0	;assume disabled	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #TextMonoOver	bne not1	;branch if not TextMonoOver;----------------------; TextMonoOver selected;----------------------	lda TMOFlag+1	;get TMO from saved	WAP	and #$0001	tax	;x=0 or x=1 now	jmp OutOK	;return without errorsnot1	cmp #OutChromaFltr	bne not2	;branch if not OutChromafltr;----------------------; OutChroma Filter selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$04	;and it out (assume	its disabled)	bne CFjmp	;branch if disabled	ldx #1	;it was enabledCFjmp		; 	rep #$30	longi on	longa on	bra OutOK	;return without errorsnot2	cmp #OutSetup	bne not3	;branch if not outsetup;----------------------; Output Setup selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c003,x	plx	and #$80	;and it out (assume	its disabled)	bne Setupjmp	;branch if disabled	ldx #1	;it was enabledSetupJmp		; 	rep #$30	longi on	longa on	bra OutOK	;return without errorsnot3	cmp #OutExtBlank	bne not4	;branch if invalid selector;----------------------; Blanking source select selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c005,x	plx	and #$10	;and it out (assume	its external)	bne SSjmp	;branch if external	ldx #1	;it was graphics (internal)SSJmp		; 	rep #$30	longi on	longa on	bra OutOK	;return without errorsnot4	cmp #VerticalBlank	bne not5	;branch if invalid;----------------------; VerticalBlank selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c000,x	plx	and #$04	;and it out (assume	its external)	bne VBSjmp	;branch if external	ldx #1	;it was graphics (internal)VBSjmp		; 	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errors	txa	sta OutStatus,s	;set returned valuenot5		; 	jmp Rid2	ENDP;           copy  GG.asm	 ;Graphics Generator routines;______________________________________________________________________________;;        VDGGControl;              (Sets the graphics generator control values);;      Input:  Selector: WORD, Selects which control to set;              OutCtrlValue: WORD, The value to set;;      output: None;______________________________________________________________________________	EXPORT VDGGControlVDGGControl	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3GGCtrlValue	equ RTL2+3Selector	equ GGCtrlValue+2;Save processor status, turn off interrupts	php	sei	;turn off interrupts;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank	sta TMOFlag;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldy #InvalidSelect	;assume bad selector error	lda GGCtrlValue,s	;get control value	tax	;save in x for now	lda Selector,s	;get selector value	cmp #MainPageLin	bne not1	;branch if not MainPageLin;----------------------; MainPageLin was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$f7	;and it out (assume	its disabled)	cpx #0	beq MPjmp	;branch if disabled	ora #$08	;or it enabledMPjmp		; 	ldx slot	sta >$00c001,x	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot1	cmp #RamPageSel	bne not2	;branch if not OutChromafltr;----------------------; RamPageSel selected;;Note:;Bit-4     Bit-5;0         0	Aux. memory;1         0	Main memory;1         1	Interlaced;----------------------	cpx #Main	;see if main	beq leavealone	;branch if doesn't affect	phx	;save x-reg.	lda TMOFlag	and #NotTMOMask	;and off TMO bit	sta TMOFlag	jsr SetupWAP	;go set the new WAP	plx	;restore x-reg.leavealone		; 	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$cf	;and it out (assume	its Aux. memory)	cpx #Aux	beq RPjmp	;branch if Aux	cpx #Main	bne Intlm	;branch if not main	ora #$10	;or it as main	jmp RPjmpIntlm	cpx #Interlace	bne ErrorJ	;branch if invalid parameter	ora #$30	;or it as interlaceRPjmp		; 	ldx slot	sta >$00c001,x	rep #$30	jmp OutOK	;return without errorsErrorJ		; 	rep #$30	longi on	longa on	ldy #InvalidParam	;incase of an error	jmp Error	;jump to errornot2	cmp #VBLInterrupt	bne not3	;branch if not VBLInterrupt select;----------------------; VBLInterrupt enable selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$bf	;and it out (assume	its disabled)	cpx #false	beq VBLjmp	;branch if disabled	cpx #true	bne ErrorJ	ora #$40	;or it enabledVBLJmp		; 	ldx slot	sta >$00c001,x	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot3	cmp #InterlaceMode	bne not4	;branch if not InterlaceMode;----------------------; Interlace mode was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c005,x	plx	and #$7f	;and it out (assume	its disabled)	cpx #0	beq IMjmp	;branch if disabled	ora #$80	;or it enabledIMJmp		; 	ldx slot	sta >$00c005,x	rep #$30	longi on	longa on	jmp OutOKnot4	cmp #ClearVBLInt	bne not5	;branch if not ClearVBLInt;----------------------; ClearVBLInt was selected;----------------------	longa off	longi off	sep #$30	lda #0	ldx slot	sta >$00c000,x	;clear vbl interrupts	rep #$30	longi on	longa on	jmp OutOknot5	cmp #LineInterrupts	bne not6	;branch if not;----------------------; LineInterrupt was	selected;----------------------	cpx #disable	bne LIEnable	;branch if enableing them;Disable line interrupts	longa off	longi off	sep #$30	ldx slot	lda >$00c001,x	and #$7f	sta >$00c001,x	;clear MegaII/VGC interrupts	rep #$30	longi on	longa on	jmp OutOk;Enabling line interruptsLIEnable		; 	cpx #enable	beq LIEOK	jmp ErrorJ	;branch if not enable or disableLIEOK		; 	longa off	longi off	sep #$30;1. Save the current processor status and disable interrutps	php	;save processor status	sei	;disable interrupts;2. Save the GGBus status and then enable it	ldx slot	lda >$00c001,x	pha	;save GG for now	ora #$01	;disable the fifos	sta >$00c001,x;3. Save the state of the VGC interrupt	register	lda >$00c023	pha	;save VGC for now too;4. Enable scan_line interrupts, disable 1 sec and external	interrupts	and #$fb	;disable 1-sec. interrupts;??????????????disable external interrupts	ora #$02	;turn on scan line interrupts	sta >$00c023;5. Disable the GGBus	lda >$00c001,x	and #$fe	;enable the fifos	sta >$00c001,x;6. Restore saved VGC interrupt register, but clear line_interrupt enable bit	pla	;get saved VGC interrupt register	and #$fd	;and out scan_line interrupts	sta >$00c023;7. Restore GGBus	pla	;get saved GGBus value	sta >$00c001,x;8. Enable Pokeys VGC interrupts	lda >$00c001,x	ora #$80	sta >$00c001,x;9. Restore processor status	plp	;restore processor status	rep #$30	longi on	longa on	jmp OutOknot6	cmp #ClearLineInt	bne not7	;branch if not;----------------------; ClearLineInt was selected;----------------------	cpx #0	beq CLI_OK	jmp ErrorJ	;branch if Nil not passedCLI_OK		; 	longa off	longi off	sep #$30;1. Save the current processor status and disable interrutps	php	;save processor status	sei	;disable interrupts;2. Save the GGBus status and then enable it	ldx slot	lda >$00c001,x	pha	;save it for now	ora #$01	;disable the fifos	sta >$00c001,x;3. Clear the VGC line interrupt (c032 bit5)	lda >$00c032	and #$df	sta >$00c032;4. Restore GGBus	pla	;get saved value back	sta >$00c001,x;5. Restore processor status	plp	;restore processor status	rep #$30	longi on	longa on	jmp OutOknot7	cmp #GGBus	bne not8	;branch if not;----------------------; GGBus was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$fe	;and it out (assume	its disabled)	cpx #disable	beq GGBjmp	;branch if disabled	cpx #enable	beq GGB_OK	jmp ErrorJGGB_OK		; 	ora #$01	;or it enabledGGBjmp		; 	ldx slot	sta >$00c001,x	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errorsnot8		; Error		; 	jmp Rid4	ENDP;______________________________________________________________________________;;        VDGGStatus;              (Gets the current status	of the graphics generator control);;      Input:  WordSpace: WORD, Space for result;              Selector: WORD, Selects which control to set;;      output: GGGetStatus: Word, Current Status Value;______________________________________________________________________________	EXPORT VDGGStatusVDGGStatus	PROC		;using EquatesSavedBank	equ 2RTL1	equ SavedBank+1RTL2	equ RTL1+3Selector	equ RTL2+3GGGetStatus	equ Selector+2;Save processor status, turn off interrupts	php;Save the users data bank register on the stack	phb	;save data bank reg.	phk	;push programs bank	plb	;set data bank to programs bank;Now get slot number from WAP	and #SlotMask	;and out all but slot no. from WAP	sta slot	ldx #0	;assume disabled	ldy #InvalidSelect	;assume bad selector error	lda Selector,s	;get selector value	cmp #MainPageLin	bne not1	;branch if not MainPageLin;----------------------; MainPageLin was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$08	;and it out (assume	its disabled)	beq MPjmp	;branch if disabled	ldx #1	;indicate enabledMPjmp		; 	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot1	cmp #RamPageSel	bne not2	;branch if not OutChromafltr;----------------------; RamPageSel selected;;Note:;Bit-4     Bit-5;0         0	Aux. memory;1         0	Main memory;1         1	Interlaced;----------------------	longa off	longi off	sep #$30	ldx slot	lda >$00c001,x	and #$30	;and it out	tax	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot2	cmp #VBLInterrupt	bne not3	;branch if not VBLInterrupt select;----------------------; VBLInterrupt enable selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	and #$40	;and it out (assume	its disabled)	beq VBLjmp	;branch if disabled	ldx #1	;indicate its enabledVBLJmp		; 	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot3	cmp #InterlaceMode	bne not4	;branch if not InterlaceMode;----------------------; Interlace mode was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c005,x	plx	and #$80	;and it out (assume	its disabled)	beq IMjmp	;branch if disabled	ldx #1	;indicate its enabledIMJmp		; 	rep #$30	longi on	longa on	jmp OutOK	;return without errorsNot4	cmp #DisplayField	bne not5	;branch if not;----------------------; DisplayField was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c000,x	plx	and #$20	;and it out (assume	its disabled)	beq DFjmp	;branch if disabled	ldx #1	;indicate enabledDFjmp		; 	rep #$30	longi on	longa on	jmp OutOK	;return without errorsnot5	cmp #VBLIntRequest	bne not6	;branch if not;----------------------; VBLIntRequest selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c000,x	plx	and #$40	;and it out	beq Isnoton	;branch if not on	ldx #1Isnoton		; 	rep #$30	longi on	longa on	jmp OutOknot6	cmp #LineInterrupts	bne not7	;branch if not;----------------------; LineInterrupt was	selected;----------------------	longa off	longi off	sep #$30*** 11-Feb-91 DAL.  This wasn't quite right before.  It wasn't doing the*** REP #$30 before jumping to OutOk, and it wasn't loading X with 0 or 1*** (it was returning 0 or $80 instead).  Let's try it again.******	ldx slot***	lda >$00c001,x***	and #$80******	tax***	jmp OutOk******	rep #$30***	longi on***	longa on	phx	ldx slot	lda >$00c001,x	plx	rep #$30	longi on	longa on	and #$0080	beq @isNotOn	ldx #1@isNotOn	jmp OutOknot7	cmp #GGBus	bne not8	;branch if not;----------------------; GGBus was selected;----------------------	longa off	longi off	sep #$30	phx	ldx slot	lda >$00c001,x	plx	ldx #disable	and #$01	;and it out (assume	its disabled)	beq GGBjump	;branch if disabled	ldx #enableGGBjump		; 	rep #$30	longi on	longa on	jmp OutOknot8	cmp #LineIntRequest	bne not9	;branch if not;----------------------; LineIntRequest was selected;----------------------	longa off	longi off	sep #$30;First see if the VGC Interrupts are enabled	phx	ldx slot	lda >$00c001,x	plx	and #$80	beq VIRjmp;Now see if an interrupt is pending	phx	ldx slot	lda >$00c000,x	plx	and #$80	beq VIRjmp	ldx #1VIRjmp		; 	rep #$30	longi on	longa onOutOK	ldy #0	;indicate no errors	txa	sta GGGetStatus,s	;set returned valuenot9		; 	jmp Rid2	ENDP	END